local currentInstance = nil


-- ========================================================


function PlayerLoader:__init()

    -- {
    --    humanRootTF     = nil,
    --    switchablePlayerTF = nil,
    -- }
    self.params = nil
    
    self.controller = nil
end


function PlayerLoader:__delete()
    self.co_1 = nil
    self.emptyFunc = nil
end


function PlayerLoader:Awake()
    if currentInstance == nil then 
        currentInstance = self
    else 
        assert( false, "不允许存在 第二个 PlayerLoader 实例" )
    end 
end


function PlayerLoader:Start()
    KTool.SetActive(self.controller.gameObject, true)
    assert(self.initPosTF)

    local luaParams = KTool.GetComponent(self.controller.gameObject, typeof(LuaParameters))
    assert( luaParams )

    self.isLoadBySelf = LuaParametersReader.Read( luaParams, "isLoadBySelf", LuaParametersType.Bool ) -- 自己主动加载prefabs,还是直接用别人加载好的
    self.defaultHumanPrefabPath = LuaParametersReader.Read( luaParams, "humanRootPath", LuaParametersType.String ) -- 指定 human prefab path, debug 阶段用

    self.playerParams = {}
    self.playerParams.initPos = self.initPosTF.position
    self.playerParams.initRoleDir = Vector3.ProjectOnPlane( self.initPosTF.forward, Vector3.up ) 
    self.playerParams.initLookDir = self.initPosTF.forward -- todo: 未来在 prefab 中增加这个参数


    self.playerParams.vcamHeight_Cat            = LuaParametersReader.Read( luaParams, "vcamHeight_Cat", LuaParametersType.Float ) -- 角色相机参数 - 猫形态
    self.playerParams.vcamRadius_Cat            = LuaParametersReader.Read( luaParams, "vcamRadius_Cat", LuaParametersType.Float ) -- 角色相机参数 - 猫形态
    self.playerParams.vcamShoulderOffset_Cat    = LuaParametersReader.Read( luaParams, "vcamShoulderOffset_Cat", LuaParametersType.Vector3 ) -- 角色相机参数 - 猫形态

    self.playerParams.vcamHeight_Human          = LuaParametersReader.Read( luaParams, "vcamHeight_Human", LuaParametersType.Float ) -- 角色相机参数 - 人形态
    self.playerParams.vcamRadius_Human          = LuaParametersReader.Read( luaParams, "vcamRadius_Human", LuaParametersType.Float ) -- 角色相机参数 - 人形态
    self.playerParams.vcamShoulderOffset_Human  = LuaParametersReader.Read( luaParams, "vcamShoulderOffset_Human", LuaParametersType.Vector3 ) -- 角色相机参数 - 人形态


    -- 得到 人猫初始形态:
    local ParamsMorphologyType = { Human=0,Cat=1 } -- 必须和 LuaParameters inspector 面板上的一致;
    local morphologyType = LuaParametersReader.Read( luaParams, "morphologyType", LuaParametersType.Enum, ParamsMorphologyType )
    self.playerParams.initMorphologyType = morphologyType == ParamsMorphologyType.Human and RoleMorphologyType.Human or RoleMorphologyType.Cat


    DreamSpaceLuaUtils.StopCoroutine( self.co_1 )
    self.co_1 = cs_coroutine.start(function()
        self:DelayInit()
    end) 
end



function PlayerLoader:DelayInit()
    
    if self.isLoadBySelf == true then 
        -- =========== 自己来加载 prefabs ==================

        self:StartLoadAsync( self.defaultHumanPrefabPath )
        -- 等待加载完成:
        while true  do 
            if self:IsAllLoadingFinished() == true then 
                break
            end 
            coroutine.yield(Yielders.EndOfFrame)
        end
        ---
        local humanLoader = self.loaders["human"]
        if isNotNull(humanLoader) and humanLoader.IsSuccess==true then 
            local newgo = humanLoader:Instantiate()
            self.humanRootTF = newgo.transform      
        else 
            printError("koko - human prefab 异步加载失败")
            return
        end
        ---
        local switchablePlayerLoader = self.loaders["switchablePlayer"]
        if isNotNull(switchablePlayerLoader) and switchablePlayerLoader.IsSuccess==true then 
            local newgo = switchablePlayerLoader:Instantiate()
            self.switchablePlayerTF = newgo.transform      
        else 
            printError("koko - switchablePlayer prefab 异步加载失败")
            return
        end 
    else 
        -- =========== 外部已经加载好了 prefabs, 会通过 params 传递给本实例 ==================

        -- 只等待有限帧
        for i=1, DreamSpaceStates.DelayInitWaitFrames do 
            if isNotNull(self.params) then 
                break
            end 
            coroutine.yield(Yielders.EndOfFrame)
        end
        ---
        assert( isNotNull(self.params), "始终没能等到 外部装填 params" )
        self.humanRootTF = self.params.humanRootTF
        self.switchablePlayerTF = self.params.switchablePlayerTF
        assert( self.humanRootTF and self.switchablePlayerTF )
    end

    -- ============================= 
    cs_coroutine.yield_return( PlayerLoader._DoAssemble( self.humanRootTF, self.switchablePlayerTF, self.playerParams ) )
end




function PlayerLoader:OnDestroy()
    currentInstance = nil
    --- 

    if self.isLoadBySelf == true then 
        self:ReleaseAllLoader()
    end

    DreamSpaceLuaUtils.StopCoroutine( self.co_1 )
    ---
    self:Delete()
end


function PlayerLoader.WaitInstance()
    -- 只等待有限帧
    for i=1, DreamSpaceStates.DelayInitWaitFrames do 
        if isNotNull(currentInstance) then 
            break
        end 
        coroutine.yield(Yielders.EndOfFrame)
    end 
    assert( isNotNull(currentInstance), "始终没能等到 PlayerLoader 实例化, 请检查场景" )
end

function PlayerLoader.GetInstance()
    return currentInstance
end


