-- 第三种初始方法, 不需要在场景中放置 switchablePlayerLoader.prefab, 而是所有数据都通过参数传入本函数
---@param humanRootTF UnityEngine.Transform
---@param switchablePlayerTF UnityEngine.Transform
---@param playerParams table or nil @ 为空时将使用默认值
function PlayerLoader.Assemble(
    humanRootTF,
    switchablePlayerTF,
    -- playerParams 的内容:
    -- {
    --      initPos,
    --      initRoleDir,            -- 角色初始朝向
    --      initLookDir,            -- 第三人称跟随相机的初始观察方向
    --      initHumanScale,          -- 角色缩放比例 (人形态)  注意: 这个值不会去主动改写 角色碰撞体的尺寸; 对此参考下方的 humanCapsuleRadius 系列参数
    --      ---
    --      ---                     人形态 KinematicCharacterMotor 的 capsule 碰撞体参数;
    --      humanCapsuleRadius,         -- (可为 nil)
    --      humanCapsuleHeight,         -- (可为 nil)
    --      humanCapsuleYOffset         -- (可为 nil)
    --      ---
    --      ---                     猫形态的相机参数:
    --      vcamHeight_Cat,             -- (可为 nil)
    --      vcamRadius_Cat,             -- (可为 nil)
    --      vcamShoulderOffset_Cat,     -- (可为 nil)
    --      ---                     人形态的相机参数:
    --      vcamHeight_Human,           -- (可为 nil)
    --      vcamRadius_Human,           -- (可为 nil)
    --      vcamShoulderOffset_Human,   -- (可为 nil)
    --      ---
    --      isCat,
    --      isIgnoreJumpHint,  -- (可为 nil)  屏蔽 cat jump hint 功能
    -- }
    playerParams
)

    assert( isNotNull(humanRootTF) and isNotNull(switchablePlayerTF) )
    ---
    playerParams = checkTable(playerParams)

    if isNull(playerParams.initPos)  then 
        playerParams.initPos = Vector3.zero
    end 

    if isNull(playerParams.initRoleDir)  then 
        playerParams.initRoleDir = Vector3( 0, 0, 1 )
    end 
    playerParams.initRoleDir = Vector3.ProjectOnPlane( playerParams.initRoleDir, Vector3.up )

    if isNull(playerParams.initLookDir)  then 
        playerParams.initLookDir = Vector3( 0, 0, 1 )
    end 

    if isNull(playerParams.initHumanScale)  then 
        playerParams.initHumanScale = Vector3.one
    end 

    if type(playerParams.isCat) ~= "boolean"  then 
        playerParams.isCat = true
    end 

    if type(playerParams.vcamHeight_Cat) ~= "number"  then 
        playerParams.vcamHeight_Cat = 0.25
    end 
    if type(playerParams.vcamRadius_Cat) ~= "number"  then 
        playerParams.vcamRadius_Cat = 2.7
    end 
    if isNull(playerParams.vcamShoulderOffset_Cat) then 
        playerParams.vcamShoulderOffset_Cat = Vector3.zero
    end 
    ---
    if type(playerParams.vcamHeight_Human) ~= "number"  then 
        playerParams.vcamHeight_Human = 1
    end 
    if type(playerParams.vcamRadius_Human) ~= "number"  then 
        playerParams.vcamRadius_Human = 4.5
    end 
    if isNull(playerParams.vcamShoulderOffset_Human) then 
        playerParams.vcamShoulderOffset_Human = Vector3.zero
    end 
    ---
    if      type(playerParams.humanCapsuleRadius) == "number"
        or  type(playerParams.humanCapsuleHeight) == "number"
        or  type(playerParams.humanCapsuleYOffset) == "number"
    then 
        if type(playerParams.humanCapsuleRadius) ~= "number"  then 
            playerParams.humanCapsuleRadius = 0.5
        end 
        if type(playerParams.humanCapsuleHeight) ~= "number"  then 
            playerParams.humanCapsuleHeight = 2
        end 
        if type(playerParams.humanCapsuleYOffset) ~= "number"  then 
            playerParams.humanCapsuleYOffset = 1
        end
    end 

    ---  
    playerParams.initMorphologyType = (playerParams.isCat==true) and RoleMorphologyType.Cat or RoleMorphologyType.Human
    --- 
    cs_coroutine.yield_return( PlayerLoader._DoAssemble( humanRootTF, switchablePlayerTF, playerParams ) )
end




function PlayerLoader._DoAssemble(  
    humanRootTF, 
    switchablePlayerTF,
    playerParams
)
    assert( isTable(playerParams) and isNotNull(humanRootTF) and isNotNull(switchablePlayerTF) )

    -- ============================= 
    humanRootTF:SetParent( switchablePlayerTF, false )
    humanRootTF.gameObject.name = "Human"
    humanRootTF.position = Vector3.zero
    switchablePlayerTF.position = playerParams.initPos
    switchablePlayerTF.rotation = Quaternion.identity
    --- 
    -- local humanAnimatorTF = nil
    -- for i=0, humanRootTF.childCount-1 do   -- 非递归
    --     local childTF = humanRootTF:GetChild(i)
    --     local comp = KTool.GetComponent(childTF.gameObject, typeof(RootMotion))
    --     if isNotNull(comp) then 
    --         humanAnimatorTF = childTF
    --         break
    --     end 
    -- end
    -- if isNull(humanAnimatorTF) then 
    --     printError("没找到 humanAnimatorTF")
    --     return
    -- end
    local humanAnimatorTF = DreamSpaceLuaUtils.FindFirstChildByComponent( humanRootTF, typeof(RootMotion) )
    assert(isNotNull(humanAnimatorTF))

    -- 人形态的 模型比例 和 capsule 碰撞体尺寸:
    if isNotNull(playerParams.initHumanScale) then 
        humanAnimatorTF.localScale = playerParams.initHumanScale
    end 

    if type(playerParams.humanCapsuleRadius) == "number" then
        local kcMotor = KTool.GetComponent(humanRootTF.gameObject, typeof(KinematicCharacterMotor))
        kcMotor:SetCapsuleDimensions( playerParams.humanCapsuleRadius, playerParams.humanCapsuleHeight, playerParams.humanCapsuleYOffset )
    end
    
    ---
    local createPlayerTF = switchablePlayerTF:Find("CreatePlayer")
    local createPlayerComp = DreamSpaceLuaUtils.GetLuaScr(createPlayerTF.gameObject, "Game.DreamSpace.CharacterController.CreatePlayer" )
    assert( createPlayerComp )

    -- ! 等一帧来确保 PMAnimator, AnimationAdapter 实例执行完自己的 Start(); 在单lua场景测试中遇到此问题
    coroutine.yield(Yielders.EndOfFrame) 
    createPlayerComp:Init( humanRootTF, humanAnimatorTF, playerParams ) 
end



-- =========================================== Self ================================================ --

-- 外部准备好 prefabs 资源
function PlayerLoader:SetParams( params_ )
    assert( type(params_) == "table" and isNotNull(params_.humanRootTF) and (params_.switchablePlayerTF) )
    self.params = params_
end 



function PlayerLoader:StartLoadAsync( humanPrefabPath_ )
    self.loaders = {}

    local switchablePlayerPath = "DreamSpace/Gameplay/SwitchablePlayeForLua.prefab" -- 角色壳的 path 暂时是固定的

    self.loaders["switchablePlayer"] = ResourceModule.LoadBundleAsync(switchablePlayerPath, nil, true)
    self.loaders["human"] = ResourceModule.LoadBundleAsync(humanPrefabPath_, nil, true)

    --end 
end



function PlayerLoader:IsAllLoadingFinished()
    for name,loader in pairs(self.loaders) do 
        if loader.IsSuccess == false then 
            return false 
        end 
    end 
    return true
end


function PlayerLoader:ReleaseAllLoader()
    for _,loader in pairs(self.loaders) do
        loader:Release()
    end
end









return PlayerLoader